import Foundation
import AppKit
import Combine

@MainActor
class SubDisplayWindowManager: NSObject, NSWindowDelegate {
    // 소유하고 있는 RemoteSession (약한 참조여야 할 수도 있음, 구조에 따라 결정)
    let remoteSession: RemoteSession

    // DisplayID를 키로 사용하여 열려있는 윈도우와 세션 티켓을 관리
    struct WindowState {
        let window: SubDisplayWindow
        // 티켓을 유지하고 있어야 프로젝션 세션이 종료되지 않음
        let ticket: RemoteSession.SessionReferenceTicket
        let viewModel: SessionWindowViewModel
    }

    private(set) var windows: [Int: WindowState] = [:]

    init(remoteSession: RemoteSession) {
        self.remoteSession = remoteSession
    }

    /// 특정 디스플레이 ID에 대한 윈도우를 엽니다.
    func spawn(for displayID: Int) async throws {
        // 1. 이미 열려있다면 해당 윈도우를 포커스
        if let state = windows[displayID] {
            state.window.makeKeyAndOrderFront(nil)
            return
        }

        // 2. RemoteSession.Projection으로부터 세션 구독 티켓 발급 (비동기)
        // (이 과정에서 필요한 경우 서버에 새 프로젝션 세션을 요청함)
        guard let projection = remoteSession.projection else { return }
        let ticket = try await projection.subscribeProjectionSession(for: displayID)

        // 3. 서브 윈도우용 ViewModel 생성 (Main과 분리된 상태 관리)
        let subViewModel = SessionWindowViewModel()
        subViewModel.bind(settingsStore: SettingsStore.shared)

        // 4. 윈도우 생성 및 설정
        let window = SubDisplayWindow(
            displayID: displayID,
            remoteSession: remoteSession,
            viewModel: subViewModel
        )
        window.delegate = self // 닫기 이벤트 감지용

        // 5. 상태 저장 및 윈도우 표시
        windows[displayID] = WindowState(
            window: window,
            ticket: ticket,
            viewModel: subViewModel
        )

        window.makeKeyAndOrderFront(nil)
    }

    /// 특정 디스플레이의 윈도우를 닫습니다.
    func destroy(for displayID: Int) {
        guard let state = windows[displayID] else { return }

        state.window.close()
        // 딕셔너리에서 제거되면 Ticket이 해제(deinit)되면서 
        // RemoteSession.Projection의 레퍼런스 카운트가 감소함 -> 세션 종료 트리거
        windows.removeValue(forKey: displayID)
    }

    /// 모든 보조 윈도우를 닫습니다. (메인 윈도우 종료 시 호출)
    func destroyAll() {
        for (id, _) in windows {
            destroy(for: id)
        }
    }

    // MARK: - NSWindowDelegate
    func windowWillClose(_ notification: Notification) {
        guard let window = notification.object as? SubDisplayWindow else { return }

        // 사용자가 X 버튼을 눌러 닫은 경우 리소스 정리
        destroy(for: window.targetDisplayID)
    }
}

import Foundation
import AppKit
import SwiftUI

class SubDisplayWindow: NSWindow {
    let targetDisplayID: Int

    init(displayID: Int, remoteSession: RemoteSession, viewModel: SessionWindowViewModel) {
        self.targetDisplayID = displayID

        // 1. NSWindow 초기화 (타이틀바, 리사이즈 가능 등)
        super.init(
            contentRect: NSRect(x: 0, y: 0, width: 800, height: 600),
            styleMask: [.titled, .closable, .miniaturizable, .resizable],
            backing: .buffered,
            defer: false
        )

        self.title = "Display #\(displayID)" // 나중에 디스플레이 이름으로 업데이트 가능
        self.minSize = NSSize(width: 640, height: 480)
        self.isReleasedWhenClosed = false
        self.center()

        // 2. SwiftUI Root View 구성
        // 기존 RemoteSessionProjectionView를 재사용하되, sourceDescriptor를 고정
        let rootView = RemoteSessionProjectionView(
            remoteSession: remoteSession,
            projection: remoteSession.projection!,
            hidio: remoteSession.hidio!,
            // Binding.constant를 사용하여 뷰 내부에서 변경하지 못하도록 함 (단방향)
            sourceDescriptor: .constant(.displayID(displayID))
        )
        .environmentObject(viewModel)
        .environmentObject(SettingsStore.shared)

        // 3. NSHostingView 설정
        self.contentView = NSHostingView(rootView: rootView)
    }
}
